'use client'

import { useState } from 'react'
import Sidebar from '@/components/Sidebar'
import TabRegistrar from '@/components/TabRegistrar'
import TabPagamentos from '@/components/TabPagamentos'
import TabConsulta from '@/components/TabConsulta'
import TabDashboard from '@/components/TabDashboard'
import TabJuridico from '@/components/TabJuridico'

export type Tab = 'dashboard' | 'registrar' | 'pagamentos' | 'consulta' | 'juridico'

const LOGO_AVICENNA = 'data:image/png;base64,'
const LOGO_ARQUIMEDES = 'data:image/png;base64,'

export default function Home() {
  const [tab, setTab] = useState<Tab>('dashboard')

  return (
    <div style={{ display: 'flex', flexDirection: 'column', minHeight: '100vh' }}>
      <header style={{
        background: '#1a2c5b',
        padding: '0 28px',
        height: 56,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        flexShrink: 0,
        zIndex: 10,
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 16 }}>
          <img src={LOGO_AVICENNA} alt="Colégio Avicenna" style={{ height: 32, objectFit: 'contain' }} />
          <div style={{ width: 1, height: 24, background: 'rgba(255,255,255,0.35)' }} />
          <img src={LOGO_ARQUIMEDES} alt="Colégio Arquimedes" style={{ height: 32, objectFit: 'contain' }} />
        </div>
        <div style={{
          fontSize: 11,
          fontWeight: 700,
          color: 'rgba(255,255,255,0.7)',
          letterSpacing: '0.14em',
          textTransform: 'uppercase',
        }}>
          Portal de Metas
        </div>
      </header>

      <div style={{ display: 'flex', flex: 1 }}>
        <Sidebar tab={tab} setTab={setTab} />
        <main style={{ flex: 1, padding: '32px', overflowY: 'auto' }}>
          {tab === 'dashboard'  && <TabDashboard />}
          {tab === 'registrar'  && <TabRegistrar />}
          {tab === 'pagamentos' && <TabPagamentos />}
          {tab === 'consulta'   && <TabConsulta />}
          {tab === 'juridico'   && <TabJuridico />}
        </main>
      </div>
    </div>
  )
}
